mapper.select:
SELECT p.id, p.employee_id as employeeId, e.real_name as employeeName, e.emp_no as empNo, p.month, p.score, p.evaluation, p.evaluator_id as evaluatorId, admin.real_name as evaluatorName FROM performance p LEFT JOIN employee e ON p.employee_id = e.id LEFT JOIN employee admin ON p.evaluator_id = admin.id
AND p.employee_id = #{employeeId}
AND e.real_name LIKE CONCAT('%', #{employeeName}, '%')
AND e.emp_no LIKE CONCAT('%', #{empNo}, '%')
AND p.month = #{month}
ORDER BY p.month DESC, p.employee_id ASC
